begin;
create table public.birdshop_services (
 slug text primary key check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
 data jsonb not null check(jsonb_typeof(data)='object'),
 packages jsonb not null default '[]' check(jsonb_typeof(packages)='array'),
 is_visible boolean not null default true,
 deleted_at timestamptz,
 updated_by uuid,
 updated_at timestamptz not null default now()
);
alter table public.birdshop_services enable row level security;
revoke all on public.birdshop_services from public,anon,authenticated;
grant select on public.birdshop_services to authenticated;
grant all on public.birdshop_services to service_role;
create policy owner_catalog_read on public.birdshop_services for select to authenticated using(public.is_birdshop_owner());

