create table public.birdshop_service_purchases (
 request_id uuid primary key,
 fingerprint jsonb not null,
 conversation_id uuid not null references public.service_conversations(id) on delete restrict,
 payment_request_id uuid not null unique references public.service_payment_requests(id) on delete restrict,
 created_at timestamptz not null default now()
);
alter table public.birdshop_service_purchases enable row level security;
revoke all on public.birdshop_service_purchases from public,anon,authenticated;
grant all on public.birdshop_service_purchases to service_role;
create function public.birdshop_buy_service_package(p_request_id uuid,p_slug text,p_tier text,p_name text,p_email text,p_expected_cents bigint)
returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.birdshop_services%rowtype; pack jsonb; existing public.birdshop_service_purchases%rowtype;
 c jsonb; payment_id uuid; fingerprint jsonb; token text;
begin
 perform private.birdshop_require_server();
 if p_request_id is null or p_tier not in ('starter','standard','premium') or length(trim(p_name)) not between 2 and 100 or length(p_email)>320 or p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Invalid request.'; end if;
 fingerprint:=jsonb_build_object('slug',p_slug,'tier',p_tier,'name',trim(p_name),'email',lower(trim(p_email)),'cents',p_expected_cents);
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,9));
 select * into existing from public.birdshop_service_purchases where request_id=p_request_id;
 if found then
  if existing.fingerprint<>fingerprint then raise exception 'Request changed. Start a new purchase.'; end if;
  select public_token into token from public.service_conversations where id=existing.conversation_id and deleted_at is null;
  if token is null then raise exception 'Conversation unavailable.'; end if;
  return jsonb_build_object('public_token',token,'payment_request_id',existing.payment_request_id);
 end if;
 select * into s from public.birdshop_services where slug=p_slug and is_visible and deleted_at is null for share;
 if not found or not coalesce((s.data->>'available')::boolean,false) then raise exception 'Service unavailable.'; end if;
 select x into pack from jsonb_array_elements(s.packages) x where x->>'id'=p_tier and x->>'enabled'='true';
 if pack is null or (pack->>'cents')::bigint not between 50 and 99999999 or length(trim(pack->>'scope'))<5 then raise exception 'Package unavailable.'; end if;
 if p_expected_cents is null or p_expected_cents<>(pack->>'cents')::bigint then raise exception 'Package price changed. Refresh before purchasing.'; end if;
 c:=public.birdshop_create_conversation('service',trim(p_name),lower(trim(p_email)),null,
 left(s.data->>'name'||' — '||(pack->>'name'),180),
 'Selected '||(pack->>'name')||': '||(pack->>'scope')||E'\nIncluded: '||coalesce((select string_agg(value,E'\n') from jsonb_array_elements_text(pack->'includes')),''),
 p_slug,s.data->>'name',p_tier,pack->>'name',null,null,null,null);
 update public.service_conversations set package_id=p_tier,package_name=pack->>'name' where id=(c->>'conversation_id')::uuid;
 insert into public.service_payment_requests(conversation_id,amount,currency,title,description,status,previous_workflow_status)
 values((c->>'conversation_id')::uuid,(pack->>'cents')::numeric/100,'usd',left(s.data->>'name'||' — '||(pack->>'name'),180),
 left((pack->>'scope')||E'\n'||coalesce((select string_agg(value,E'\n') from jsonb_array_elements_text(pack->'includes')),''),2000),'pending',
 (select workflow_status from public.service_conversations where id=(c->>'conversation_id')::uuid)) returning id into payment_id;
 insert into public.birdshop_service_purchases(request_id,fingerprint,conversation_id,payment_request_id) values(p_request_id,fingerprint,(c->>'conversation_id')::uuid,payment_id);
 insert into public.service_messages(conversation_id,sender_type,sender_label,body)
 values((c->>'conversation_id')::uuid,'system','BirdShop','Your package is selected. Once payment is confirmed, use this private chat to share your requirements and arrange the next steps.');
 return jsonb_build_object('public_token',c->>'public_token','payment_request_id',payment_id);
end $$;
revoke all on function public.birdshop_buy_service_package(uuid,text,text,text,text,bigint) from public,anon,authenticated;
grant execute on function public.birdshop_buy_service_package(uuid,text,text,text,text,bigint) to service_role;
create function private.birdshop_service_catalog_audit() returns trigger language plpgsql security definer set search_path='' as $$
begin
 insert into public.birdshop_audit_log(actor_id,action,details) values(new.updated_by,
 case when new.deleted_at is not null then 'service_removed' when tg_op='INSERT' then 'service_created' else 'service_updated' end,
 jsonb_build_object('slug',new.slug,'visible',new.is_visible));
 return new;
end $$;
revoke all on function private.birdshop_service_catalog_audit() from public,anon,authenticated;
create trigger service_catalog_audit after insert or update on public.birdshop_services for each row execute function private.birdshop_service_catalog_audit();
notify pgrst,'reload schema';
commit;
